import org.springframework.web.bind.annotation.*;

// ❌ OLD: The thread-per-request model. Each concurrent request holds
// a thread while it waits on blocking calls (HTTP client, DB). With
// 200 threads and each request spending 100ms waiting on I/O, the app
// saturates around 2000 req/s regardless of CPU — most threads are
// idle, just parked on I/O. Tomcat's default 200 threads cap
// concurrency, and queues build up under load.
@RestController
public class OrderControllerLegacy {
  @GetMapping("/order/{id}")
  public Order get(@PathVariable long id) {
    User u = userClient.get(id); // ❌ OLD: blocking HTTP — thread parked
    return orderService.findByUser(u); // ❌ OLD: blocking DB — thread parked
  }
}

