import org.springframework.web.bind.annotation.*;
import reactor.core.publisher.Mono;

// ✅ NEW: The reactive chain is non-blocking end to end. The event
// loop thread initiates the I/O, is freed while it's in flight, and
// resumes when the data arrives. Thousands of concurrent requests
// share a handful of event-loop threads.
@RestController
public class OrderController {
  private final UserClient userClient; // reactive WebClient
  private final OrderService orderService;

  @GetMapping("/order/{id}")
  public Mono<Order> get(@PathVariable long id) {
    return userClient.get(id) // ✅ NEW: Mono<User>, non-blocking
        .flatMap(orderService::findByUser) // ✅ NEW: Mono<Order>
        .map(order -> order.withTimestamp(now())); // ✅ NEW: transform
  }

  // ⚠️ IMPORTANT: never block inside the chain (Thread.sleep,
  // blocking DB/HTTP). Offload blocking work instead:
  //   .publishOn(Schedulers.boundedElastic())
}

